begin isolation level repeatable read read only;
with logs as (select id,created_at,target_id,case when pg_input_is_valid(details,'jsonb') then details::jsonb else '{}'::jsonb end d from activity_logs),
latest_area as (select distinct on (d#>>'{context,shiftId}') id,created_at,target_id,d from logs where d#>>'{context,shiftId}' is not null and d#>>'{context,operation}' in ('shift_area_assign','shift_area_restore','cross_committee_area_cleanup','security_cross_committee_area_cleanup','committee_transfer_area_cleanup','cross_committee_area_migration_cleanup') order by d#>>'{context,shiftId}',created_at desc,id desc),
rows as (select s.id,s.volunteer_id,concat(v.first_name,' ',v.last_name) name,c.name committee,v.status volunteer_status,s.day_key,s.shift_key,s.area_id,a.name area,s.created_at,s.updated_at,l.id audit_id,l.created_at audit_at,
case when l.id is null then 'sin_auditoria_individual_area' when s.area_id::text is distinct from l.d#>>'{context,areaId}' then 'discrepancia_area' when l.target_id<>s.volunteer_id::text or l.d#>>'{context,dayKey}'<>s.day_key or l.d#>>'{context,shiftKey}'<>s.shift_key then 'discrepancia_contexto' else 'coincide' end audit_result,
case when v.status='archived' then 'oculto_voluntario_archivado' when s.day_key='TEST_INSERT_RT' then 'fuera_calendario' else 'incluido_consulta_areas' end visibility
from shifts s join volunteers v on v.id=s.volunteer_id join committees c on c.id=v.committee_id left join committee_areas a on a.id=s.area_id left join latest_area l on l.d#>>'{context,shiftId}'=s.id::text)
select jsonb_build_object('cutoff',now(),'total',(select count(*) from shifts),'audit_total',(select count(*) from activity_logs),'rows',(select jsonb_agg(jsonb_build_array(id,volunteer_id,name,committee,volunteer_status,day_key,shift_key,area_id,area,created_at,updated_at,audit_id,audit_at,audit_result,visibility) order by committee,name,day_key,shift_key) from rows),'counts',(select jsonb_agg(x) from (select committee,count(*) total,count(*) filter(where area_id is not null) with_area,count(*) filter(where visibility='incluido_consulta_areas') included,count(*) filter(where visibility='oculto_voluntario_archivado') archived,count(*) filter(where visibility='fuera_calendario') invalid_day from rows group by committee order by committee)x),'integrity',(select jsonb_build_object('orphan_volunteer',count(*) filter(where v.id is null),'orphan_area',count(*) filter(where s.area_id is not null and a.id is null),'cross_committee',count(*) filter(where a.id is not null and a.committee_id is distinct from v.committee_id),'archived_area',count(*) filter(where a.status='archived')) from shifts s left join volunteers v on v.id=s.volunteer_id left join committee_areas a on a.id=s.area_id));commit;

begin read only;
with logs as (select *,case when pg_input_is_valid(details,'jsonb') then details::jsonb else '{}'::jsonb end d from activity_logs),
area_logs as (select *, d#>>'{context,shiftId}' sid,d#>>'{context,areaId}' expected_area, d#>>'{context,operation}' op from logs where d#>>'{context,operation}' in ('shift_area_assign','shift_area_restore','cross_committee_area_cleanup','security_cross_committee_area_cleanup','committee_transfer_area_cleanup','cross_committee_area_migration_cleanup')),
latest as (select distinct on (sid) * from area_logs where sid is not null order by sid,created_at desc,id desc),
comp as (select l.id log_id,l.created_at log_at,l.target_id volunteer_id,concat(v.first_name,' ',v.last_name) name,c.name committee,l.sid,l.d#>>'{context,dayKey}' day_key,l.d#>>'{context,shiftKey}' shift_key,l.op,l.expected_area,a.name expected_name,s.id current_id,s.area_id::text actual_area,aa.name actual_name,s.updated_at,
case when s.id is null then 'missing_shift' when s.area_id::text is distinct from l.expected_area then 'area_mismatch' else 'match' end result
from latest l left join shifts s on s.id::text=l.sid left join volunteers v on v.id::text=l.target_id left join committees c on c.id=v.committee_id left join committee_areas a on a.id::text=l.expected_area left join committee_areas aa on aa.id=s.area_id)
select jsonb_build_object('area_log_count',(select count(*) from area_logs),'results',(select jsonb_agg(x) from (select result,count(*) n from comp group by 1)x),'exceptions',(select jsonb_agg(comp) from comp where result<>'match'),
'integrity',(select jsonb_build_object('orphan_volunteer',count(*) filter(where v.id is null),'orphan_area',count(*) filter(where s.area_id is not null and a.id is null),'cross_committee',count(*) filter(where a.id is not null and a.committee_id is distinct from v.committee_id),'archived_volunteer',count(*) filter(where v.status='archived'),'archived_area',count(*) filter(where a.status='archived'),'without_committee',count(*) filter(where v.committee_id is null)) from shifts s left join volunteers v on v.id=s.volunteer_id left join committee_areas a on a.id=s.area_id),
'duplicates',(select jsonb_agg(x) from (select volunteer_id,day_key,shift_key,count(*) n from shifts group by 1,2,3 having count(*)>1)x),
'bulk_logs',(select jsonb_agg(x) from (select id,description,d from logs where d#>>'{context,operation}' in ('shift_area_bulk_assign','cross_committee_area_cleanup','security_cross_committee_area_cleanup'))x)
); commit;

begin read only; with logs as (select *,case when pg_input_is_valid(details,'jsonb') then details::jsonb else '{}'::jsonb end d from activity_logs), ar as (select distinct on (d#>>'{context,shiftId}') * from logs where d#>>'{context,shiftId}' is not null and d#>>'{context,operation}' in ('shift_area_assign','shift_area_restore','cross_committee_area_cleanup','security_cross_committee_area_cleanup') order by d#>>'{context,shiftId}',created_at desc,id desc), missing as (
select l.id audit_id,l.created_at area_log_at,l.target_id,concat(v.first_name,' ',v.last_name) name,v.status,c.name committee,l.d#>>'{context,dayKey}' day_key,l.d#>>'{context,shiftKey}' shift_key,a.name previous_area,l.d#>>'{context,shiftId}' previous_shift_id,s2.id replacement_id,a2.name replacement_area,s2.created_at replacement_created,
(select max(l2.created_at) from logs l2 where l2.target_id=l.target_id and l2.created_at>l.created_at and coalesce(l2.d->>'operation',l2.d#>>'{context,operation}')='remove_shift' and coalesce(l2.d->>'dayKey',l2.d#>>'{context,dayKey}')=l.d#>>'{context,dayKey}' and coalesce(l2.d->>'shiftKey',l2.d#>>'{context,shiftKey}')=l.d#>>'{context,shiftKey}') removal_at
from ar l left join shifts s on s.id::text=l.d#>>'{context,shiftId}' left join volunteers v on v.id::text=l.target_id left join committees c on c.id=v.committee_id left join committee_areas a on a.id::text=l.d#>>'{context,areaId}' left join shifts s2 on s2.volunteer_id=v.id and s2.day_key=l.d#>>'{context,dayKey}' and s2.shift_key=l.d#>>'{context,shiftKey}' left join committee_areas a2 on a2.id=s2.area_id where s.id is null)
select jsonb_build_object('summary',(select jsonb_agg(x) from (select (removal_at is not null) removal_logged,(replacement_id is not null) replaced,(replacement_area is not null) replacement_has_area,count(*) n from missing group by 1,2,3)x),'rows',(select jsonb_agg(missing) from missing)); commit;
